import java.util.*;
import java.util.stream.*;
public class Main {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        int n = s.nextInt();
        long[] v = new long[n];
        for (int i = 0; i < n; i++) v[i] = s.nextLong();
        long sum = Arrays.stream(v).filter(x -> x % 2 == 0).map(x -> x * x).sum();
        long odd = Arrays.stream(v).filter(x -> x % 2 != 0).count();
        System.out.println(sum);
        System.out.println(odd);
    }
}
